def transform(g):
    H,W=len(g),len(g[0])
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    seen=set(); comps=[]
    for c in [(i,j) for i in range(H) for j in range(W) if g[i][j]!=bg]:
        if c in seen: continue
        q=deque([c]); seen.add(c); comp=[]
        while q:
            i,j=q.popleft(); comp.append((i,j))
            for dii,djj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni,nj=i+dii,j+djj
                if 0<=ni<H and 0<=nj<W and g[ni][nj]!=bg and (ni,nj) not in seen:
                    seen.add((ni,nj)); q.append((ni,nj))
        comps.append(comp)
    stampc=max(comps,key=len)
    markers=[c for comp in comps if len(comp)==1 for c in comp]
    r0=min(i for i,_ in stampc); r1=max(i for i,_ in stampc)
    c0=min(j for _,j in stampc); c1=max(j for _,j in stampc)
    stamp=[[g[i][j] for j in range(c0,c1+1)] for i in range(r0,r1+1)]
    h,w=len(stamp),len(stamp[0]); mr,mc=(r0+r1)//2,(c0+c1)//2
    out=[row[:] for row in g]
    for mi,mj in markers:
        for a in range(h):
            for b in range(w):
                ri,rj=mi+((r0+a)-mr), mj+((c0+b)-mc)
                if 0<=ri<H and 0<=rj<W:
                    out[ri][rj]=stamp[a][b]
    return out
